  SELECT id, dept_id, salary,
    DENSE_RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rank_no
  FROM employees WHERE salary IS NOT NULL
) WHERE rank_no <= 3 ORDER BY dept_id, salary DESC, id;

